{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Zouk_Unicommerce_B2B_Orders AS WITH WIP_Latest AS ( SELECT LOWER(CAST(Item_id AS STRING)) AS SKU, MAX(SAFE.PARSE_DATE(\'%Y-%m-%d\', Data_Updated_Date)) AS Latest_Date FROM MapleMonk.Zouk_Zouk_S3_TranZact_WIP WHERE Item_id IS NOT NULL GROUP BY SKU ), WIP_Final AS ( SELECT LOWER(CAST(w.Item_id AS STRING)) AS SKU, SUM(SAFE_CAST(w.Estimated_Quantity AS INT64) - SAFE_CAST(w.Quantity_Produced AS INT64)) AS WIP FROM MapleMonk.Zouk_Zouk_S3_TranZact_WIP w JOIN WIP_Latest l ON LOWER(CAST(w.Item_id AS STRING)) = l.SKU AND SAFE.PARSE_DATE(\'%Y-%m-%d\', w.Data_Updated_Date) = l.Latest_Date GROUP BY SKU ) , Combined AS ( SELECT cast(nullif(u.Initial_Order_Date,\"\")as datetime) as Initial_Order_date, DATE_DIFF(CURRENT_DATE(), DATE(initial_order_date), DAY) AS TAT, u.Order_Date, u.Dispatch_Date, u.invoice_date as invoiceDate, u.Shipping_Last_Update_Date, u.Order_Id, u.reference_code, NULLIF(u.invoice_Code, \'\') AS invoiceCode, u.shipping_package_code as shippingPackageCode, u.sale_order_item_code as saleOrderItemCode, u.order_status, u.Marketplace_SKU, u.SKU, COALESCE(fsm_mpsku.brand, fsm_sku.brand) AS Brand, COALESCE(fsm_mpsku.commonsku, fsm_sku.commonsku) AS commonsku, COALESCE(fsm_mpsku.collection, fsm_sku.collection) AS Collection, COALESCE(fsm_mpsku.category, fsm_sku.category) AS Product_Category, COALESCE(fsm_mpsku.print, fsm_sku.print) AS Print, COALESCE(fsm_mpsku.Product_Type, fsm_sku.Product_Type) AS Product_Type, COALESCE(fsm_mpsku.Name, fsm_sku.Name) AS Marketplace_SKU_Name, u.Product_Name, u.Marketplace, u.FINAL_MARKETPLACE, u.MARKETPLACE_SEGMENT, u.TYPE_OF_SALE, u.Selling_Price, u.Payment_Mode, SAFE_CAST(w.WIP AS INT64) AS WIP FROM `MapleMonk.zouk_new_unicommerce_factitems_intermediate` u LEFT JOIN ( SELECT * FROM `MapleMonk.FINAL_SKU_MASTER` QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(commonsku) ORDER BY 1) = 1 ) fsm_mpsku ON LOWER(u.Marketplace_sku) = LOWER(fsm_mpsku.commonsku) LEFT JOIN ( SELECT * FROM `MapleMonk.FINAL_SKU_MASTER` QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(commonsku) ORDER BY 1) = 1 ) fsm_sku ON LOWER(u.SKU) = LOWER(fsm_sku.commonsku) LEFT JOIN WIP_Final w ON LOWER(u.SKU) = w.SKU where lower(Order_Status) not like \'%cancel%\' ) , Ranked_Unfulfillable AS ( SELECT SKU, saleOrderItemCode, MIN(index_in_sequence) AS cum_index FROM ( SELECT LOWER(SKU) AS SKU, LOWER(saleOrderItemCode) AS saleOrderItemCode, ROW_NUMBER() OVER ( PARTITION BY LOWER(SKU) ORDER BY Initial_Order_Date, saleOrderItemCode ) - 1 AS index_in_sequence FROM Combined WHERE LOWER(order_status) = \'unfulfillable\' ) GROUP BY SKU, saleOrderItemCode ) SELECT c.*, r.cum_index, CASE WHEN LOWER(c.order_status) = \'unfulfillable\' AND c.WIP > r.cum_index THEN 1 ELSE 0 END AS wip_inventory_flag FROM Combined c LEFT JOIN Ranked_Unfulfillable r ON lower(c.sku) = lower(r.sku) AND lower(c.order_status) = \'unfulfillable\' AND lower(c.saleOrderItemCode) = lower(r.saleOrderItemCode)",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            